namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private static int _taskHandUnknownPatchCalls;
    private static void TaskHandUnknownPrefix()=>_taskHandUnknownPatchCalls++;

    private async Task AssertTaskHandCallbackClosureAsync(CombatState live,Player player)
    {
        SetStage("task_hand_callback_closure");
        await CreatureCmd.SetMaxHp(player.Creature,75);
        await CreatureCmd.SetCurrentHp(player.Creature,60);
        foreach(var potion in player.PotionSlots.ToArray())potion?.Discard();
        for(int i=0;i<4;i++)await NGame.Instance!.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
        const BindingFlags flags=TaskHandCallbackProof.Flags;
        NPlayerHand hand=NPlayerHand.Instance!;
        FieldInfo Field(Type t,string n)=>t.GetField(n,flags)!;
        FieldInfo prefsField=Field(typeof(NPlayerHand),"_prefs"),filterField=Field(typeof(NPlayerHand),"_currentSelectionFilter"),modeField=Field(typeof(NPlayerHand),"_currentMode");
        object oldPrefs=prefsField.GetValue(hand)!;object? oldFilter=filterField.GetValue(hand);object oldMode=modeField.GetValue(hand)!;
        if(hand.CurrentMode!=NPlayerHand.Mode.Play||oldFilter is not null)
            throw new InvalidOperationException("Expected ordinary play mode without selection filter.");
        var first=TaskHandCallbackProof.Capture(hand);
        if(!first.SlotsCertified||first.GoldCallbacks!=0)throw new InvalidOperationException("Baseline callback slots are not empty: "+JsonSerializer.Serialize(first));
        var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();
        string Parent(CombatPredictionSimulator sim)=>DescribeContinuationContractState(sim,root,player);
        string parentBefore=Parent(parent),liveBefore=ContinuationStamp.CaptureLive(live).StateText;
        var snapshots=live.Enemies.Select(e=>CaptureActual(live,player,e)).ToArray();
        var nested=typeof(CardSelectCmd).GetNestedTypes(BindingFlags.NonPublic|BindingFlags.Public)
            .Single(t=>t.Name=="<>c");
        MethodInfo constant=nested.GetMethods(flags).Single(m=>m.Name.StartsWith("<FromHand>",StringComparison.Ordinal)
            &&m.ReturnType==typeof(bool)&&m.GetParameters() is [var parameter]&&parameter.ParameterType==typeof(CardModel));
        object constantTarget=Field(nested,"<>9").GetValue(null)!;
        var nativeConstant=(Func<CardModel,bool>)constant.CreateDelegate(typeof(Func<CardModel,bool>),constantTarget);
        if(!TaskHandCallbackProof.IsNativeConstantLeaf(nativeConstant))throw new InvalidOperationException("Native true filter body changed.");
        var constantPrefs=(CardSelectorPrefs)oldPrefs;constantPrefs.ShouldGlowGold=nativeConstant;
        TaskHandCallbackProof.Result constantResult;
        bool goldValue;
        try
        {
            prefsField.SetValue(hand,constantPrefs);
            constantResult=TaskHandCallbackProof.Capture(hand);
            if(!constantResult.SlotsCertified||constantResult.ConstantLeafCallbacks!=1)throw new InvalidOperationException("Constant native callback refused.");
            goldValue=nativeConstant(player.PlayerCombatState!.Hand.Cards.First());
            if(!goldValue)throw new InvalidOperationException("Native constant predicate returned false.");
            for(int i=0;i<snapshots.Length;i++)AssertSnapshotEqual(CaptureActual(live,player,live.Enemies[i]),snapshots[i],"HandGoldConstant","NativeLeafNoOp");
            if(Parent(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore)throw new InvalidOperationException("Constant callback changed full combat state/history/RNG.");
        }
        finally{prefsField.SetValue(hand,oldPrefs);}
        bool armed=false,healed=false;int calls=0,unknownInspectionCalls=0;
        bool UnknownFilter(CardModel card){unknownInspectionCalls++;return true;}
        bool UnknownGold(CardModel card)
        {
            calls++;
            if(armed&&!healed&&player.Creature.CurrentHp<60){healed=true;player.Creature.HealInternal(2);}
            return false;
        }
