        void Reject(string name,string reason)
        {
            for(int i=0;i<2;i++)
            {
                var result=TaskHandCallbackProof.Capture(hand);
                if((reason=="patch:"?result.SitesCertified:result.SlotsCertified)||!result.Refusals.Any(r=>r.Contains(reason,StringComparison.Ordinal)))
                    throw new InvalidOperationException("Hand callback source admitted: "+name);
                cases.Add(new{name,boundary=i==0?"prospective-root":"prospective-live",result,productionIntegrated=false});
            }
        }
        filterField.SetValue(hand,(Func<CardModel,bool>)UnknownFilter);
        try{Reject("unknown-filter-in-play-mode","selection-filter");}finally{filterField.SetValue(hand,oldFilter);}
        var unknownPrefs=(CardSelectorPrefs)oldPrefs;unknownPrefs.ShouldGlowGold=UnknownGold;
        prefsField.SetValue(hand,unknownPrefs);
        try{Reject("unknown-gold-with-null-filter-and-play-mode","gold-glow");}finally{prefsField.SetValue(hand,oldPrefs);}
        modeField.SetValue(hand,(NPlayerHand.Mode)999);
        try{Reject("unknown-mode","unknown-mode");}finally{modeField.SetValue(hand,oldMode);}
        var harmony=new Harmony("combatsolver.testing.task-hand-callback-closure");
        var methods=new[]{AccessTools.PropertyGetter(typeof(NPlayerHand),"SelectModeGoldGlowOverride"),
            AccessTools.Method(typeof(NPlayerHand),"RevalidateSelectionAfterStateChange"),
            AccessTools.PropertyGetter(typeof(NHandCardHolder),"ShouldGlowGold"),
            AccessTools.PropertyGetter(typeof(CardSelectorPrefs),"ShouldGlowGold")};
        MethodInfo prefix=typeof(UnattendedTestRunner).GetMethod(nameof(TaskHandUnknownPrefix),flags)!;
        _taskHandUnknownPatchCalls=0;
        foreach(var method in methods)
        {
            try{harmony.Patch(method,prefix:new HarmonyMethod(prefix));Reject("unknown-patch-"+method.Name,"patch:");}
            finally{harmony.Unpatch(method,HarmonyPatchType.All,harmony.Id);}
        }
        prefsField.SetValue(hand,constantPrefs);
        try
        {
            harmony.Patch(constant,prefix:new HarmonyMethod(prefix));Reject("patched-native-constant-leaf","gold-glow");
        }
        finally{harmony.Unpatch(constant,HarmonyPatchType.All,harmony.Id);prefsField.SetValue(hand,oldPrefs);}
        if(calls!=0||unknownInspectionCalls!=0||_taskHandUnknownPatchCalls!=0)
            throw new InvalidOperationException("Admission invoked an unknown callback or patch.");
        var children=Enumerable.Range(0,16).Select(_=>parent.Fork()).ToArray();
        filterField.SetValue(hand,(Func<CardModel,bool>)UnknownFilter);
        try
        {
            await Task.WhenAll(children.Select(child=>Task.Run(()=>
            {
                using var isolation=SimulationNotificationIsolation.Enter();
                if(!first.SlotsCertified||Parent(child)!=parentBefore)throw new InvalidOperationException("Frozen branch changed with live callback.");
                child.Damage(player.Creature,1,ValueProp.Unblockable|ValueProp.Unpowered,null);
                string changed=Parent(child);
                if(child.State.GetCreature(player.Creature).CurrentHp!=59||changed==parentBefore||Parent(child.Fork())!=changed)
                    throw new InvalidOperationException("Owned damage/Fork failed isolation.");
            })));
        }
        finally{filterField.SetValue(hand,oldFilter);}
        if(Parent(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore||unknownInspectionCalls!=0)
            throw new InvalidOperationException("Parallel actions changed parent/live or invoked live predicate.");
        var tracker=CombatManager.Instance.StateTracker;
        FieldInfo trackerEvent=Field(typeof(CombatStateTracker),"CombatStateChanged");object? trackerBefore=trackerEvent.GetValue(tracker);
        var directFields=new[]{Field(typeof(Creature),"CurrentHpChanged"),Field(typeof(Creature),"MaxHpChanged")};
        object?[] directBefore=directFields.Select(f=>f.GetValue(player.Creature)).ToArray();
        object evidence;
        try
        {
            prefsField.SetValue(hand,unknownPrefs);
            var counterRoot=CombatRootSnapshot.Capture(live);var counterParent=counterRoot.ForkSimulator();var child=counterParent.Fork();
            string counterBefore=DescribeContinuationContractState(counterParent,counterRoot,player);
            int bound=StrategicHpRecoveryBound.ComponentHealingUpperBound(counterParent,player,0,useReviewedSources:true);
            if(!counterRoot.UsesPruningComponentHealingCertificate||bound!=0||filterField.GetValue(hand) is not null||hand.IsInCardSelection)
                throw new InvalidOperationException("Expected unchanged zero certificate with null filter and ordinary mode.");
            armed=true;
            using(SimulationNotificationIsolation.Enter())child.Damage(player.Creature,6,ValueProp.Unblockable|ValueProp.Unpowered,null);
            int shadowHp=child.State.GetCreature(player.Creature).CurrentHp;
            if(calls!=0)throw new InvalidOperationException("Shadow invoked native hand callback.");
            await CreatureCmd.Damage(new BlockingPlayerChoiceContext(),player.Creature,6,ValueProp.Unblockable|ValueProp.Unpowered,null!);
            for(int i=0;i<10&&!healed;i++)await NGame.Instance!.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
            if(!healed||calls<1||player.Creature.CurrentHp!=shadowHp+2||Parent(parent)!=parentBefore
                ||DescribeContinuationContractState(counterParent,counterRoot,player)!=counterBefore
                ||!Equals(trackerBefore,trackerEvent.GetValue(tracker))
                ||directFields.Where((f,i)=>!Equals(directBefore[i],f.GetValue(player.Creature))).Any())
                throw new InvalidOperationException("Gold-glow native recovery counterexample did not reproduce or changed outer audience.");
            evidence=new{bound,counterRoot.UsesPruningComponentHealingCertificate,counterRoot.UsesKnownNativeHealingPolicy,
                shadowHp,nativeHp=player.Creature.CurrentHp,calls,healed,selectionFilterNull=true,isInCardSelection=false,
                directAndTrackerAudienceUnchanged=true,counterParentFullStateHistoryRngUnchanged=true};
        }
        finally{armed=false;prefsField.SetValue(hand,oldPrefs);filterField.SetValue(hand,oldFilter);modeField.SetValue(hand,oldMode);}
