            nativeConstantDirectInvocations=1,nativeHolderGetterInvokedInPositiveFixture=false,sitePatchInventory=new[]{
                AccessTools.PropertyGetter(typeof(NPlayerHand),"SelectModeGoldGlowOverride"),AccessTools.Method(typeof(NPlayerHand),"RevalidateSelectionAfterStateChange"),
