using System.Collections.Immutable;
using System.Reflection;
using HarmonyLib;
using MegaCrit.Sts2.Core.CardSelection;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Nodes.Cards.Holders;
using MegaCrit.Sts2.Core.Nodes.Combat;

namespace CombatSolver;

// Invocation-only subproof. It does not certify card visual refresh, factories,
// pending selection continuations, future sources or the whole HP event chain.
internal static class TaskHandCallbackProof
{
    internal const BindingFlags Flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly;
    private static readonly Guid GameMvid=new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    internal sealed record Result(bool SlotsCertified,bool SitesCertified,ImmutableArray<string> Refusals,int FilterCallbacks,int GoldCallbacks,
        int ConstantLeafCallbacks,int Mode,bool ComparisonPresent,bool WholeHealthCertificate=false);

    private static bool Patched(MethodBase method)
    {
        var p=Harmony.GetPatchInfo(method);
        return p is not null&&p.Prefixes.Count+p.Postfixes.Count+p.Transpilers.Count+p.Finalizers.Count!=0;
    }

    internal static bool IsNativeConstantLeaf(Delegate callback)
    {
        MethodInfo method=callback.Method;
        if(method.Module.ModuleVersionId!=GameMvid||method.IsStatic||method.IsVirtual||method.ReturnType!=typeof(bool)
            ||method.GetParameters() is not [var parameter]||parameter.ParameterType!=typeof(CardModel)||Patched(method))return false;
        MethodBody? body=method.GetMethodBody();
        byte[]? il=body?.GetILAsByteArray();
        return body is not null&&body.ExceptionHandlingClauses.Count==0&&body.LocalVariables.Count==0
            &&il is [0x16 or 0x17,0x2a];
    }

    internal static Result Capture(NPlayerHand hand)
    {
        var reasons=ImmutableArray.CreateBuilder<string>();
        if(typeof(NPlayerHand).Module.ModuleVersionId!=GameMvid)reasons.Add("native-version");
        var methods=new[]{AccessTools.PropertyGetter(typeof(NPlayerHand),"IsInCardSelection"),
            AccessTools.PropertyGetter(typeof(NPlayerHand),"CurrentMode"),AccessTools.PropertyGetter(typeof(NPlayerHand),"SelectModeGoldGlowOverride"),
            AccessTools.Method(typeof(NPlayerHand),"OnCombatStateChanged"),AccessTools.Method(typeof(NPlayerHand),"RevalidateSelectionAfterStateChange"),
            AccessTools.Method(typeof(NPlayerHand),"UpdateSelectModeCardVisibility"),AccessTools.Method(typeof(NHandCardHolder),"UpdateCard"),
            AccessTools.PropertyGetter(typeof(NHandCardHolder),"ShouldGlowGold"),AccessTools.PropertyGetter(typeof(CardSelectorPrefs),"ShouldGlowGold")};
        foreach(var method in methods)
            if(Patched(method))reasons.Add("patch:"+method.DeclaringType!.FullName+"."+method.Name);
        FieldInfo Field(Type type,string name)=>type.GetField(name,Flags)
            ??throw new InvalidOperationException("Hand callback field contract changed: "+type.FullName+"."+name);
        var filter=(Delegate?)Field(typeof(NPlayerHand),"_currentSelectionFilter").GetValue(hand);
        object prefs=Field(typeof(NPlayerHand),"_prefs").GetValue(hand)!;
        var gold=(Delegate?)Field(typeof(CardSelectorPrefs),"<ShouldGlowGold>k__BackingField").GetValue(prefs);
        var comparison=(Delegate?)Field(typeof(CardSelectorPrefs),"<Comparison>k__BackingField").GetValue(prefs);
        int siteReasons=reasons.Count;
        int mode=(int)(NPlayerHand.Mode)Field(typeof(NPlayerHand),"_currentMode").GetValue(hand)!;
        if(mode is <0 or >3)reasons.Add("unknown-mode:"+mode);
        int leaf=0;
        int Check(Delegate? value,string source)
        {
            if(value is null)return 0;
            var callbacks=value.GetInvocationList();
            foreach(var callback in callbacks)
                if(IsNativeConstantLeaf(callback))leaf++;
                else reasons.Add("unproven-callback:"+source+":"+callback.Method.DeclaringType?.FullName+"."+callback.Method.Name);
            return callbacks.Length;
        }
        int filters=Check(filter,"selection-filter"),golds=Check(gold,"gold-glow");
        return new(reasons.Count==siteReasons,siteReasons==0,reasons.ToImmutable(),filters,golds,leaf,mode,comparison is not null);
    }
}

